from openhisto.patch_extraction import (
    ExtractionConfig, extract_grid,
)

summary = extract_grid(
    "slide.svs", "patches.h5",
    ExtractionConfig(
        patch_size=512, target_mag=20,
    ),
)

from openhisto.stain_transfer import (
    DomainSpec, TransferConfig, normalize,
)

normalize(
    "patches.h5", "normalized.h5",
    DomainSpec(
        method="reinhard",
        references=("reference.png",),
    ),
    TransferConfig(device="cpu"),
)

from openhisto.feature_encoder import (
    EncodeConfig, encode_slide,
)

report = encode_slide(
    "patches.h5", "slide.h5ad",
    models=["phikon_v2"],
    config=EncodeConfig(
        device="cpu", batch_size=1,
    ),
)

from openhisto.mil.models.code_bases import (
    create_model,
)

backbone = create_model(
    "abmil",
    input_dim=1024,
    num_classes=3,
)

